<?php
namespace Tests\Unit;use PHPUnit\Framework\TestCase;
class OfflineApprovedRankPhaseRTest extends TestCase
{private function source(string$p):string{return file_get_contents(ROOTPATH.$p);}public function testRequiredInputsAndPastDateValidation():void{$s=$this->source('app/Services/OfflineApprovedRankService.php');foreach(['SIGNED_APPROVED_DOCUMENT_REQUIRED','APPROVAL_DATE_REQUIRED','EFFECTIVITY_DATE_REQUIRED','PAST_EFFECTIVITY_DATE_NOT_ALLOWED']as$c)self::assertStringContainsString($c,$s);}public function testFinalizedExactContextAndRankRequired():void{$s=$this->source('app/Services/OfflineApprovedRankService.php');foreach(['CASE_NOT_FINALIZED_READY_FOR_PRINTING','OFFICIAL_DOCUMENT_CONTEXT_MISMATCH','APPROVED_RANK_MUST_MATCH_FINAL_HR_RECOMMENDATION','APPROVED_RANK_NOT_SYSTEM_VALID']as$c)self::assertStringContainsString($c,$s);}public function testFuturePendingAndTodayActivationPath():void{$s=$this->source('app/Services/OfflineApprovedRankService.php');self::assertStringContainsString("'approved_pending_effectivity':'active'",$s);self::assertStringContainsString('activateApprovedResult',$s);self::assertStringContainsString("if(\$status==='active')",$s);}public function testFutureDoesNotMutatePresentRank():void{$s=$this->source('app/Services/OfflineApprovedRankService.php');$before=substr($s,0,strpos($s,'private function activateApprovedResult'));self::assertStringNotContainsString("->update(['current_rank_title'",$before);}public function testPendingGuardOverlapAndPermanentHistory():void{$m=$this->source('app/Database/Migrations/2026-09-15-000013_CreateOfflineApprovedRanks.php');foreach(['pending_personnel_guard','uq_approved_rank_pending_personnel','personnel_rank_history','effective_to']as$x)self::assertStringContainsString($x,$m);$s=$this->source('app/Services/OfflineApprovedRankService.php');self::assertStringContainsString('ACTIVE_PENDING_FUTURE_RANK_EXISTS',$s);self::assertStringContainsString('RANK_EFFECTIVE_PERIOD_OVERLAP',$s);self::assertStringNotContainsString('delete()',$s);}public function testDuplicateIsIdempotentAndHrOnly():void{$m=$this->source('app/Database/Migrations/2026-09-15-000013_CreateOfflineApprovedRanks.php');self::assertStringContainsString('uq_approved_rank_case',$m);$s=$this->source('app/Services/OfflineApprovedRankService.php');self::assertStringContainsString('if($existing)return$existing',$s);self::assertStringContainsString('APPROVED_RANK_HR_ONLY',$s);}public function testDocumentAccessIsHrOrOwnerButNotReviewer():void{$s=$this->source('app/Services/OfflineApprovedRankService.php');self::assertStringContainsString("if(!\$this->isHr(\$actor)&&!\$this->isOwner(\$actor,\$r))",$s);self::assertStringContainsString('SIGNED_APPROVED_DOCUMENT_ACCESS_DENIED',$s);self::assertStringContainsString('reviewerRecord',$s);self::assertStringNotContainsString('signed_document',$this->method($s,'private function reviewerRecord','private function isReviewer'));}public function testNotificationsExcludeDocumentAccess():void{$s=$this->source('app/Services/OfflineApprovedRankService.php');self::assertStringContainsString('DEPARTMENT_HEAD',$s);self::assertStringContainsString('Effectivity Date',$s);$notify=substr($s,strpos($s,'private function notify'));self::assertStringNotContainsString('signed_document',$notify);}private function method(string$s,string$from,string$to):string{$a=strpos($s,$from);$b=strpos($s,$to,$a);return substr($s,$a,$b-$a);}}
